#include "stdlib/math/base/special/truncbf.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/math/base/special/truncf.h"
#include "stdlib/math/base/assert/is-nanf.h"
#include "stdlib/math/base/assert/is-infinitef.h"
#include <stdint.h>

/**
* Rounds a single-precision floating-point number toward zero to n digits in base b.
*
* @param x    input value
* @param n    number of digits
* @param b    base
* @return     output value
*
* @example
* float y = stdlib_base_truncbf( 3.14159f, 2, 10 );
* // returns 3.14f
*/
float stdlib_base_truncbf( const float x, const int32_t n, const int32_t b ) {
	float s;

	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_infinitef( x ) || x == 0.0f ) {
		return x;
	}
	if ( b == 0 ) {
		return 0.0f / 0.0f;
	}
	s = stdlib_base_powf( (float)b, (float)n );
	if ( stdlib_base_is_infinitef( s ) ) {
		return x;
	}
	return stdlib_base_truncf( x * s ) / s;
}

